class Solution { public int[] getOrder(int[][] tasks){int n=tasks.length;int[][] indexed=new int[n][3];for(int i=0;i<n;i++)indexed[i]=new int[]{tasks[i][0],tasks[i][1],i};Arrays.sort(indexed,Comparator.comparingInt(a->a[0]));PriorityQueue<int[]> ready=new PriorityQueue<>((a,b)->a[1]!=b[1]?a[1]-b[1]:a[2]-b[2]);int[] answer=new int[n];int next=0,done=0;long time=0;while(done<n){if(ready.isEmpty())time=Math.max(time,indexed[next][0]);while(next<n&&indexed[next][0]<=time)ready.offer(indexed[next++]);int[] task=ready.poll();answer[done++]=task[2];time+=task[1];}return answer;} }
